
/*
 * trials.c
 * --------
 *  This was generated by an LLM since the original file 
 *  was not available on the Stanford site.
 *
 * Four implementations of computing 2^n:
 *   A: pow()
 *   B: exp2()
 *   C: Iterative multiplication
 *   D: Bit shifting
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>

/* Version A: use pow() */
__attribute__((noinline))
double versionA(int n)
{
    return pow(2.0, (double)n);
}

/* Version B: use exp2() */
__attribute__((noinline))
double versionB(int n)
{
    return exp2((double)n);
}

/* Version C: iterative multiplication */
__attribute__((noinline))
uint64_t versionC(int n)
{
    uint64_t result = 1;

    for (int i = 0; i < n; i++) {
        result *= 2;
    }

    return result;
}

/* Version D: use the binary representation */
__attribute__((noinline))
uint64_t versionD(int n)
{
    return UINT64_C(1) << n;
}

int main(int argc, char *argv[])
{
    int n = 10;

    if (argc > 1) {
        n = atoi(argv[1]);
    }

    if (n < 0 || n > 62) {
        fprintf(stderr, "n must be between 0 and 62\n");
        return EXIT_FAILURE;
    }

    printf("Computing 2^%d:\n", n);

    printf("Version A (pow):  %.0f\n", versionA(n));
    printf("Version B (exp2): %.0f\n", versionB(n));
    printf("Version C (loop): %llu\n",
           (unsigned long long)versionC(n));
    printf("Version D (shift): %llu\n",
           (unsigned long long)versionD(n));

    return EXIT_SUCCESS;
}

